<div class="modal fade" id="locationModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><form method="POST" id="locationForm" class="modal-content">@csrf @method('PATCH')<div class="modal-header"><h5 class="modal-title">Allocate Location</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="mb-3"><label class="form-label">District *</label><select name="district_id" id="allocDistrict" class="form-select" required><option value="">Select</option>@foreach($districts as $d)<option value="{{ $d->id }}">{{ $d->name }}</option>@endforeach</select></div><div class="mb-3"><label class="form-label">Taluka <span class="text-muted">(optional)</span></label><select name="taluka_id" id="allocTaluka" class="form-select"><option value="">All talukas</option>@foreach($talukas as $t)<option value="{{ $t->id }}" data-district="{{ $t->district_id }}">{{ $t->name }}</option>@endforeach</select></div><div><label class="form-label">City / Village <span class="text-muted">(optional)</span></label><select name="locality_id" id="allocLocality" class="form-select"><option value="">All cities / villages</option>@foreach($localities as $l)<option value="{{ $l->id }}" data-taluka="{{ $l->taluka_id }}">{{ $l->name }} ({{ ucfirst($l->type) }})</option>@endforeach</select></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary">Allocate</button></div></form></div></div>
