@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const modal=document.getElementById('locationModal'),district=document.getElementById('allocDistrict'),taluka=document.getElementById('allocTaluka'),locality=document.getElementById('allocLocality');const filter=()=>{[...taluka.options].forEach((o,i)=>{if(i)o.hidden=o.dataset.district!==district.value});[...locality.options].forEach((o,i)=>{if(i)o.hidden=o.dataset.taluka!==taluka.value})};district.addEventListener('change',()=>{taluka.value='';locality.value='';filter()});taluka.addEventListener('change',()=>{locality.value='';filter()});modal.addEventListener('show.bs.modal',e=>{const b=e.relatedTarget;document.getElementById('locationForm').action=`{{ url('/admin/volunteers/users') }}/${b.dataset.userId}/location`;district.value=b.dataset.district||'';filter();taluka.value=b.dataset.taluka||'';filter();locality.value=b.dataset.locality||''});const commissionModal=document.getElementById('commissionModal'),defaultFields=document.getElementById('defaultCommissionFields'),roleFields=document.getElementById('roleCommissionFields');const toggleCommissionFields=()=>{const isRole=document.getElementById('roleCommissionMode').checked;defaultFields.classList.toggle('d-none',isRole);roleFields.classList.toggle('d-none',!isRole);document.getElementById('defaultCommissionPoints').required=!isRole;roleFields.querySelectorAll('input').forEach(input=>input.required=isRole)};document.querySelectorAll('.commission-mode').forEach(input=>input.addEventListener('change',toggleCommissionFields));commissionModal.addEventListener('show.bs.modal',e=>{const b=e.relatedTarget;document.getElementById('commissionForm').action=`{{ url('/admin/volunteers/users') }}/${b.dataset.userId}/commission`;document.getElementById('commissionUserName').textContent=b.dataset.userName;document.getElementById(b.dataset.mode==='role_wise'?'roleCommissionMode':'defaultCommissionMode').checked=true;document.getElementById('defaultCommissionPoints').value=b.dataset.default||0;['general','matrimony','business','volunteer'].forEach(role=>document.getElementById(`roleCommission${role[0].toUpperCase()+role.slice(1)}`).value=b.dataset[role]||0);toggleCommissionFields()})});</script>@endpush
